[
  {
    "question": "Which of the following best distinguishes a DBMS from a traditional file‑based system?",
    "options": {
      "A": "A DBMS stores data in a single flat file, while a file‑based system uses multiple tables.",
      "B": "A DBMS provides a data dictionary (metadata) and supports query languages, whereas a file‑based system lacks these features.",
      "C": "A DBMS requires manual indexing of records, while a file‑based system automatically indexes data.",
      "D": "A DBMS enforces data integrity only at the application level, while a file‑based system enforces it within the operating system."
    },
    "correct_answer": "B",
    "explanation": "The syllabus notes define a DBMS as software that \"defines, stores, retrieves, protects\" data and maintains metadata (catalog). Unlike file‑based systems, a DBMS includes a data dictionary and supports declarative query languages such as SQL.",
    "difficulty": "Medium"
  },
  {
    "question": "In a DBMS, the term *metadata* most accurately refers to:",
    "options": {
      "A": "The actual user data stored in tables.",
      "B": "The set of SQL statements used to modify data.",
      "C": "Data about the structure of the database, such as schemas and constraints.",
      "D": "Temporary data created during query execution."
    },
    "correct_answer": "C",
    "explanation": "Metadata, also called the catalog, contains information about the database’s structure (schemas, tables, columns, constraints). This is explicitly listed among the retrieval keywords in the syllabus.",
    "difficulty": "Medium"
  },
  {
    "question": "Which of the following statements correctly describes *logical data independence*?",
    "options": {
      "A": "Changes to the physical storage layout do not affect the external schema seen by users.",
      "B": "Changes to the conceptual schema (e.g., adding a new attribute) do not require changes to application programs.",
      "C": "Modifying a table’s primary key automatically updates all foreign keys without programmer intervention.",
      "D": "Altering the DBMS software version does not impact existing SQL queries."
    },
    "correct_answer": "B",
    "explanation": "Logical data independence means that modifications to the conceptual schema, such as adding attributes, do not force changes in external schemas or application programs. Physical data independence (option A) refers to storage changes.",
    "difficulty": "Medium"
  },
  {
    "question": "A transaction in a DBMS is defined as a logical unit of work that moves the database from one consistent state to another. Which ACID property guarantees that once the transaction commits, its effects survive system failures?",
    "options": {
      "A": "Atomicity",
      "B": "Consistency",
      "C": "Isolation",
      "D": "Durability"
    },
    "correct_answer": "D",
    "explanation": "Durability ensures that after a transaction commits, its changes are permanently recorded and survive crashes. This is part of the ACID guarantees mentioned in the end‑of‑course capability.",
    "difficulty": "Medium"
  },
  {
    "question": "Which constraint is most appropriate for enforcing a stable business rule that a column must always contain a value?",
    "options": {
      "A": "PRIMARY KEY",
      "B": "FOREIGN KEY",
      "C": "CHECK",
      "D": "NOT NULL"
    },
    "correct_answer": "D",
    "explanation": "A NOT NULL constraint directly enforces that a column cannot store NULL values, embodying a stable business rule. While PRIMARY KEY also implies NOT NULL, the generic rule is captured by the NOT NULL constraint alone.",
    "difficulty": "Medium"
  }
]
